#!/usr/bin/env python3
"""
Cleanup script for files generated by the ABP simulator.

This script removes temporary files and results generated
during simulations to keep the project clean.
"""

import os
import glob
import shutil
from pathlib import Path

def cleanup_generated_files():
    """Cleans up files generated by the simulator."""
    
    # Directories and patterns to clean
    cleanup_patterns = [
        "core/generated/*.csv",
        "core/generated/*.json", 
        "core/generated/*.txt",
        "core/generated/*.html",
        "results/*.csv",
        "results/*.json",
        "results/*.txt",
        "charts_*",
        "*.log",
        "__pycache__",
        "**/__pycache__",
        "*.pyc",
        "**/*.pyc"
    ]
    
    cleaned_files = []
    cleaned_dirs = []
    
    print("Starting cleanup of generated files...")
    
    for pattern in cleanup_patterns:
        matches = glob.glob(pattern, recursive=True)
        
        for match in matches:
            try:
                if os.path.isfile(match):
                    os.remove(match)
                    cleaned_files.append(match)
                    print(f"  File removed: {match}")
                    
                elif os.path.isdir(match):
                    shutil.rmtree(match)
                    cleaned_dirs.append(match)
                    print(f"  Directory removed: {match}")
                    
            except Exception as e:
                print(f"  Error removing {match}: {e}")
    
    # Create required directories if they don't exist
    required_dirs = ["core/generated", "results"]
    for dir_path in required_dirs:
        Path(dir_path).mkdir(parents=True, exist_ok=True)
        print(f"  Directory created/maintained: {dir_path}")
    
    print(f"\nCleanup completed:")
    print(f"  Files removed: {len(cleaned_files)}")
    print(f"  Directories removed: {len(cleaned_dirs)}")

if __name__ == "__main__":
    cleanup_generated_files()
